//! g-xTB 2.0.1 at finite electronic temperatures (Fermi smearing) against the 2.0.1 program
//! (`xtb --gxtb --etemp T --grad [--acc 0.0001]`; data in tests/reference_v2/etemp/etemp.json,
//! generated by scripts/make_reference_v2_etemp.py), and the default conventions' analytic
//! gradients against finite differences of their own free energy.

use axtb_gxtb::scf::Setup;
use axtb_gxtb::{Conventions, ScfOptions};
use serde_json::Value;
use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/reference_v2")
}

fn rows() -> Vec<Value> {
    let doc: Value = serde_json::from_str(&std::fs::read_to_string(root().join("etemp/etemp.json")).unwrap()).unwrap();
    doc["rows"].as_array().unwrap().clone()
}

fn dir(group: &str, name: &str) -> PathBuf {
    if group == "extra" {
        root().join("etemp/extra").join(name)
    } else {
        root().join(group).join(name)
    }
}

fn molecule(group: &str, name: &str, conv: Conventions) -> axtb::Molecule {
    let d = dir(group, name);
    let input: Value = serde_json::from_str(&std::fs::read_to_string(d.join("input.json")).unwrap()).unwrap();
    let xyz = std::fs::read_to_string(d.join("mol.xyz")).unwrap();
    let uhf = input["uhf"].as_u64().unwrap() as usize;
    axtb_gxtb::model::read_xyz(&xyz, input["charge"].as_f64().unwrap(), Some(uhf), conv).unwrap()
}

/// Runs whose SCF the program ends in a regime where rounding decides the outcome: perturbing
/// kT by one ulp (2e-16 relative) in our SCF moves the result by as much as its difference to
/// the program (default thresholds: Fe4 6e-7..8e-6 Eh, TmH3 at 3000 and 5000 K 1e-6 and 2e-4
/// Eh with 53-98 and 157-250 iterations, ErF3 at 5000 K 1e-9..1e-8 Eh; tight thresholds: the
/// iteration counts of Fe4 at 1000 K (75-176 vs 119), CeCl3 at 5000 K (48-64 vs 51), ErF3 at
/// 3000 and 5000 K, stretched N2 at 5000 K (10-11 vs 11) while the energies agree to 1e-12 Eh;
/// EuCl3 at 5000 K, where the program's SCF ends at 250 iterations with the residual just above
/// the threshold and ours, as kT moves by +- 1 ulp or the summation order changes, ends at 250
/// (residual 3.4e-9 vs 2e-9) or converges in 102-247 iterations).
/// The occupations depend on the orbital energies at finite temperature, so the last-bit
/// differences of the eigensolver and exp() reach the density; the program's DIIS on these
/// slowly converging SCFs amplifies them.
fn sensitive(name: &str, etemp: f64, tight: bool) -> bool {
    if tight {
        matches!(
            (name, etemp as u32),
            ("Fe4", 1000)
                | ("CeCl3", 5000)
                | ("ErF3", 3000)
                | ("ErF3", 5000)
                | ("N2_stretched", 5000)
                | ("EuCl3", 5000)
        )
    } else {
        matches!((name, etemp as u32), ("Fe4", _) | ("TmH3", 3000) | ("TmH3", 5000) | ("ErF3", 5000))
    }
}

/// Program mode at 300, 1000, 3000 and 5000 K, the program's default thresholds, on the
/// reference molecules (without the two large ones unless ETEMP_LARGE is set; they take 30 s;
/// tests/gxtb2_reproduction.py covers them), Fe4 and stretched N2: total and electronic
/// energies, SCF iterations, failures and analytic gradients as the program's.
#[test]
fn etemp_matches_program() {
    compare(false);
}

/// The same with the program's tight thresholds (`--acc 0.0001`).
#[test]
fn etemp_matches_program_tight() {
    compare(true);
}

fn compare(tight: bool) {
    let (mut worst_e, mut worst_el, mut worst_g) = (0.0f64, 0.0f64, 0.0f64);
    let mut bad = Vec::new();
    for row0 in rows().iter().filter(|r| std::env::var("ETEMP_LARGE").is_ok() || r["group"] != "large") {
        let row = if tight { &row0["tight"] } else { row0 };
        let (group, name) = (row0["group"].as_str().unwrap(), row0["name"].as_str().unwrap());
        let etemp = row0["etemp"].as_f64().unwrap();
        let label = format!("{name} {etemp} K");
        let mol = molecule(group, name, Conventions::Gxtb);
        let setup = Setup::new(&mol, axtb_gxtb::model::Model::v2_0_1(Conventions::Gxtb)).unwrap();
        let opts = ScfOptions {
            conventions: Conventions::Gxtb,
            etemp,
            accuracy: if tight { 1e-4 } else { 1.0 },
            ..Default::default()
        };
        let res = setup.scf(&opts);
        let sens = sensitive(name, etemp, tight);
        if !row["converged"].as_bool().unwrap() {
            println!("{label:28} program SCF fails; ours: {}", if res.is_err() { "fails" } else { "converges" });
            if res.is_ok() && !sens {
                bad.push(label);
            }
            continue;
        }
        let r = match res {
            Ok(r) => r,
            Err(e) => {
                println!("{label:28} FAILED {e}");
                if !sens {
                    bad.push(label);
                }
                continue;
            }
        };
        let de = r.energies.total - row["total_energy"].as_f64().unwrap();
        let it = row["scf_iterations"].as_u64().unwrap() as usize;
        let g = setup.gradient(&r).unwrap();
        let gp = row["gradient"].as_array().unwrap();
        let mut dg: f64 = 0.0;
        for (a, ga) in g.iter().enumerate() {
            for x in 0..3 {
                dg = dg.max((ga[x] - gp[a][x].as_f64().unwrap()).abs());
            }
        }
        // the electronic energy (14 digits) includes -TS
        let del = if tight { 0.0 } else { r.energies.electronic - row["electronic_energy"].as_f64().unwrap() };
        println!(
            "{label:28} dE {de:9.1e} elec {del:9.1e} it {:3}/{it:3} grad {dg:8.1e} -TS {:10.3e}{}",
            r.iterations,
            r.energies.entropy,
            if sens { "  (rounding-sensitive)" } else { "" }
        );
        if sens {
            assert!(de.abs() < 1e-3, "{label}: {de:e}");
            if tight {
                assert!(de.abs() < 1e-11, "{label}: {de:e}");
            }
            continue;
        }
        // 1e-11 Eh, or the 12-decimal printout's summation floor of the largest molecules
        // ((H2O)100: 2-4e-11 Eh of 7644 Eh, as at 0 K)
        let scale = (r.energies.total.abs() * 6e-15).max(1e-11) / 1e-11;
        worst_e = worst_e.max(de.abs() / scale);
        worst_el = worst_el.max(del.abs() / scale);
        worst_g = worst_g.max(dg);
        if r.iterations != it {
            bad.push(label);
        }
    }
    println!("worst energy {worst_e:e}, electronic {worst_el:e}, gradient {worst_g:e}, mismatches {bad:?}");
    assert!(bad.is_empty(), "iterations or failures differ: {bad:?}");
    assert!(worst_e < 1e-11, "total energy {worst_e:e} (scaled)");
    assert!(worst_el < 1e-11, "electronic energy {worst_el:e} (scaled)");
    assert!(worst_g < 1e-9, "gradient {worst_g:e}");
}

/// Converged far enough that the 5-point differences see no SCF error: the free energy is
/// variational, so its error goes as the residual squared. Tighter thresholds sit at the
/// round-off of a heavy-element energy (CeCl3 stalled at a residual of 2.3e-11 and energy
/// changes of 2e-13 Eh on another x86-64 CPU).
fn tight(c: Conventions, etemp: f64) -> ScfOptions {
    ScfOptions {
        conventions: c,
        etemp,
        energy_tol: Some(1e-11),
        residual_tol: Some(1e-10),
        max_iter: 500,
        ..Default::default()
    }
}

/// Default conventions: the analytic gradient is the derivative of the free energy E - TS
/// (exact Fermi level, no occupation response), checked against 5-point finite differences.
#[test]
fn etemp_gradient_matches_finite_differences() {
    for (group, name, etemp) in
        [("extra", "N2_stretched", 5000.0), ("reference", "tetrachlorocuprate", 5000.0), ("elements", "CeCl3", 5000.0)]
    {
        let c = Conventions::Axtb;
        let mol = molecule(group, name, c);
        let setup = Setup::new(&mol, axtb_gxtb::model::Model::v2_0_1(c)).unwrap();
        let r = setup.scf(&tight(c, etemp)).unwrap();
        assert!(r.energies.entropy < -1e-6, "{name}: no smearing");
        let g = setup.gradient(&r).unwrap();
        let e = |m: &axtb::Molecule| {
            Setup::new(m, axtb_gxtb::model::Model::v2_0_1(c)).unwrap().scf(&tight(c, etemp)).unwrap().energies.total
        };
        let h = 5e-4;
        let mut worst: f64 = 0.0;
        for a in 0..mol.nat() {
            for x in 0..3 {
                let at = |d: f64| {
                    let mut m = mol.clone();
                    m.positions[a][x] += d;
                    e(&m)
                };
                let fd = (8.0 * (at(h) - at(-h)) - (at(2.0 * h) - at(-2.0 * h))) / (12.0 * h);
                worst = worst.max((fd - g[a][x]).abs());
            }
        }
        println!("{name:20} {etemp} K  -TS {:.3e}  max |analytic - FD| = {worst:.2e}", r.energies.entropy);
        assert!(worst < 2e-9, "{name}: {worst:e}");
    }
}
